                    api.iset_sprite_index(rt.deref(self.vars[g.VAR_obj], self, other), k.SPR_sSignGeneral);
                } else if (rt.strEq(self.strs[g.SVAR_shopType], "Bomb")) {
                    api.iset_sprite_index(rt.deref(self.vars[g.VAR_obj], self, other), k.SPR_sSignBomb);
                } else if (rt.strEq(self.strs[g.SVAR_shopType], "Weapon")) {
                    api.iset_sprite_index(rt.deref(self.vars[g.VAR_obj], self, other), k.SPR_sSignWeapon);
                } else if (rt.strEq(self.strs[g.SVAR_shopType], "Clothing")) {
                    api.iset_sprite_index(rt.deref(self.vars[g.VAR_obj], self, other), k.SPR_sSignClothing);
                } else if (rt.strEq(self.strs[g.SVAR_shopType], "Rare")) {
                    api.iset_sprite_index(rt.deref(self.vars[g.VAR_obj], self, other), k.SPR_sSignRare);
                } else if (rt.strEq(self.strs[g.SVAR_shopType], "Craps")) {
                    api.iset_sprite_index(rt.deref(self.vars[g.VAR_obj], self, other), k.SPR_sSignCraps);
                } else if (rt.strEq(self.strs[g.SVAR_shopType], "Kissing")) {
                    api.iset_sprite_index(rt.deref(self.vars[g.VAR_obj], self, other), k.SPR_sSignKissing);
                }
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("$"))) {
                g.gml_script_scrShopItemsGen(self, other);
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("d"))) {
                _ = g.gml_script_instance_create(self, other, (self.vars[g.VAR_xpos] + 8.0), (self.vars[g.VAR_ypos] + 8.0), k.OBJ_oDice);
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("D"))) {
                self.vars[g.VAR_obj] = g.gml_script_instance_create(self, other, (self.vars[g.VAR_xpos] + 8.0), (self.vars[g.VAR_ypos] + 8.0), k.OBJ_oDamsel);
                rt.ivarSet(rt.deref(self.vars[g.VAR_obj], self, other), g.VAR_forSale, 1.0);
                rt.ivarSet(rt.deref(self.vars[g.VAR_obj], self, other), g.VAR_status, 5.0);
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("s"))) {
                _ = g.gml_script_instance_create(self, other, self.vars[g.VAR_xpos], self.vars[g.VAR_ypos], k.OBJ_oSpikes);
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("S"))) {
                _ = g.gml_script_instance_create(self, other, self.vars[g.VAR_xpos], self.vars[g.VAR_ypos], k.OBJ_oSnake);
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("T"))) {
                _ = g.gml_script_instance_create(self, other, (self.vars[g.VAR_xpos] + 8.0), (self.vars[g.VAR_ypos] + 8.0), k.OBJ_oRubyBig);
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("i"))) {
                _ = g.gml_script_instance_create(self, other, self.vars[g.VAR_xpos], self.vars[g.VAR_ypos], k.OBJ_oIce);
            } else if ((rt.veq(self.vals[g.VVAR_tile], rt.vs("j")) and rt.eq(g.gml_script_rand(self, other, 1.0, 2.0), 1.0))) {
                _ = g.gml_script_instance_create(self, other, self.vars[g.VAR_xpos], self.vars[g.VAR_ypos], k.OBJ_oIce);
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("Y"))) {
                _ = g.gml_script_instance_create(self, other, self.vars[g.VAR_xpos], self.vars[g.VAR_ypos], k.OBJ_oYetiKing);
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("y"))) {
                _ = g.gml_script_instance_create(self, other, self.vars[g.VAR_xpos], self.vars[g.VAR_ypos], k.OBJ_oYeti);
            }
        }
    }
}
